import React from 'react';
import './aiDisclaimer.css';

/**
 * "This was generated by AI and can be wrong."
 *
 * Shown on every screen carrying model-generated content — the insights on the
 * result screen and the Nouri Bot conversation. Both are produced by Claude and
 * both can be confidently wrong, so the notice belongs next to the content
 * rather than buried in a settings page.
 *
 * Two variants:
 *   `inline` — a quiet strip under a block of generated text
 *   `banner` — a bordered box for a whole screen of generated content
 *
 * Deliberately not dismissible. A disclaimer the user can permanently hide
 * isn't doing the job it exists to do.
 */
export default function AiDisclaimer({ variant = 'inline', context = 'insights' }) {
  const COPY = {
    insights: {
      short: 'AI-generated · may be inaccurate',
      long:
        'These insights are generated by AI from label data and can be incomplete ' +
        'or wrong. They are general information, not medical or dietary advice. ' +
        'Check the package and talk to your pediatrician before making decisions ' +
        'about your child’s food.',
    },
    chat: {
      short: 'AI-generated · may be inaccurate',
      long:
        'Nouri is an AI assistant. It can be confidently wrong, and it only knows ' +
        'about the product on screen. It does not know your child’s medical ' +
        'history and cannot give medical or dietary advice. For anything health-' +
        'related, talk to your pediatrician.',
    },
  }[context] || {};

  if (variant === 'banner') {
    return (
      <div className="ai-disclaimer-banner">
        <span className="ai-disclaimer-badge" aria-hidden>AI</span>
        <p className="ai-disclaimer-text">{COPY.long}</p>
      </div>
    );
  }

  return (
    <div className="ai-disclaimer-inline">
      <span className="ai-disclaimer-badge sm" aria-hidden>AI</span>
      <span>{COPY.short}</span>
    </div>
  );
}
